#!/usr/bin/env python3
"""Retain the exact Maiko rectangle artwork without a retained SVG node per rectangle.
Copyright (C) 2026 Hundekraft. GPL-3.0-or-later with OP-1 firmware permission.
"""
from pathlib import Path
import xml.etree.ElementTree as ET
P=Path(__file__).resolve().parent

def generate():
    rows=[]
    for node in ET.parse(P/'plate_art.svg').getroot():
        d=node.attrib['d'].split()
        assert d[0]=='M' and d[3]=='L' and d[6]=='L' and d[9]=='L' and d[12]=='Z'
        x,y,xx,yy=map(int,(d[1],d[2],d[4],d[8]))
        assert list(map(int,(d[5],d[7],d[10],d[11])))==[y,xx,x,yy]
        c=node.attrib['fill'];rgb=tuple(int(c[i:i+2],16) for i in (1,3,5))
        rows.append((x,y,xx,yy,*rgb))
    header='/* Generated by gen_art.py from owner-authorized Maiko artwork.\n * Copyright (C) 2026 Hundekraft. GPL-3.0-or-later with OP-1 firmware permission. */\n'
    header+='static const struct { uint16_t x,y,xx,yy; uint8_t r,g,b; } plate_art[] = {\n'
    header+=''.join(' {'+','.join(map(str,row))+'},\n' for row in rows)+'};\n'
    return header

if __name__=='__main__':
    (P/'plate_art.h').write_text(generate())
    (P/'plate.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" width="320" height="160" viewBox="0 0 320 160"><!-- Exact art is drawn through the shared raster path; see plate_art.svg. --></svg>\n')
